        --border: ButtonBorder;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --shadow: none;
        --focus: Highlight;
      }

      .skip-link,
      .faq-shell,
      .example,
      .question::after {
        forced-color-adjust: auto;
      }

      .question::after {
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <main id="main">
    <div class="hero">
      <div class="eyebrow">Cat care FAQ</div>
      <h1>Everything you wanted to know about cats</h1>
      <p class="lead">A compact FAQ with quick answers about cat behavior, grooming, feeding, and everyday care.</p>
    </div>

    <section class="faq-shell" aria-labelledby="faq-title">
      <h2 id="faq-title" class="sr-only" style="position:absolute;left:-9999px;">Frequently asked questions</h2>
      <div id="app" class="faq-list"></div>
    </section>
  </main>

  <script>
    const faqData = [
      {
        question: "Why do cats knead blankets and laps?",
        answer: [
          "Kneading is a comforting behavior many cats carry into adulthood. It often shows that they feel safe, relaxed, and at ease.",
          "Some cats also knead before settling down to rest, much like a calming bedtime ritual."
        ]
      },
      {
        question: "How often should I feed a cat?",
        answer: [
          "Most adult cats do well with two measured meals a day, but the right schedule depends on age, health, and activity level.",
          "Keep portions consistent and talk with a veterinarian if your cat needs help with weight management."
        ]
      },
      {
        question: "Do indoor cats need enrichment?",
        answer: [
          "Yes. Indoor cats thrive when they can climb, scratch, hunt, and observe their surroundings.",
          "A mix of toys, window perches, puzzle feeders, and short play sessions helps prevent boredom."
        ]
      },
      {
        question: "Why do cats purr?",
        answer: [
          "Purring often signals contentment, but cats may also purr when they are nervous, seeking comfort, or healing.",
          "Context matters: look at body language, posture, and vocal tone to understand what your cat is saying."
        ]
      },
      {
        question: "How do I introduce two cats?",
        answer: [
          "Start slowly with separate spaces, scent swapping, and short supervised meetings.",
          "Let them set the pace. Gradual introductions reduce stress and give both cats time to feel secure."
        ]
      }
    ];

    function FAQItem({ question, answer, index }) {
      const contentId = `faq-answer-${index}`;
      return `
        <div class="example" data-open="false">
          <button class="question" type="button" aria-expanded="false" aria-controls="${contentId}">
            <strong>${question}</strong>
            <span>Tap to expand</span>
          </button>
          <div class="details" id="${contentId}" hidden>
            ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
          </div>
        </div>
      `;
    }

    function App(items) {
      return items.map((item, index) => FAQItem({ ...item, index })).join("");
    }

    const app = document.getElementById("app");
    app.innerHTML = App(faqData);

    app.addEventListener("click", (event) => {
      const button = event.target.closest(".question");
      if (!button) return;

      const example = button.closest(".example");
      const details = example.querySelector(".details");
      const expanded = button.getAttribute("aria-expanded") === "true";
      const nextState = !expanded;

      button.setAttribute("aria-expanded", String(nextState));
      example.dataset.open = String(nextState);
      details.hidden = !nextState;
    });
  </script>
